class Resource {
    int* data_;
public:
    Resource(size_t s) : data_(new int[s]) {}
    ~Resource() { delete[] data_; }

    // 1. Move Constructor (Rvalue reference T&&)
    Resource(Resource&& other) noexcept
        : data_(other.data_) {
        other.data_ = nullptr; // Steal and null source
    }

    // 2. Move Assignment Operator
    Resource& operator=(Resource&& other) noexcept {
        if (this != &other) {
            delete[] data_;         // Release existing
            data_ = other.data_;
            other.data_ = nullptr;
        }
        return *this;
    }
};

// 3. Forcing a Move (lvalue -> rvalue ref)
std::vector<int> source;
std::vector<int> destination = std::move(source);

// Rvalue function overloading example
void accept(std::string&& temp_str); // Accepts temporaries only
void accept(const std::string& stable_str); // Accepts lvalues or const rvalues
